  "implementation": "def solve(case):
    import json
    # Validate required top-level fields
    required_fields = ['min_cluster_size', 'clusters', 'parent']
    for field in required_fields:
        if field not in case:
            raise ValueError(f"Missing required field: {field}")
    min_cluster_size = case['min_cluster_size']
    clusters_list = case['clusters']
    parent_map = case['parent']

    # Validate clusters and parent
    if not isinstance(min_cluster_size, int) or min_cluster_size <= 0:
        raise ValueError("min_cluster_size must be a positive integer")
    if not isinstance(clusters_list, list):
        raise ValueError("clusters must be a list")
    if not isinstance(parent_map, dict):
        raise ValueError("parent must be a dict")

    # Build lookup for all clusters (including dropped) to validate and compute descendants
    all_clusters = {}
    for c in clusters_list:
        if not isinstance(c, dict):
            raise ValueError("Each cluster must be an object")
        cid = c.get('cluster_id')
        if not isinstance(cid, str):
            raise ValueError("cluster_id must be a string")
        size = c.get('size')
        if not isinstance(size, int):
            raise ValueError("size must be an integer")
        birth = c.get('birth_lambda')
        if not isinstance(birth, (int, float)):
            raise ValueError("birth_lambda must be a number")
        exits = c.get('point_exit_lambdas')
        if not isinstance(exits, list) or not all(isinstance(x, (int, float)) for x in exits):
            raise ValueError("point_exit_lambdas must be a list of numbers")
        all_clusters[cid] = {'size': size, 'birth': birth, 'exits': exits}

    # Validate parent map keys match cluster IDs
    for cid, parent in parent_map.items():
        if cid not in all_clusters:
            raise ValueError(f"Parent map key {cid} not in clusters")
        if parent is not None and parent not in all_clusters:
            raise ValueError(f"Parent {parent} for {cid} not in clusters")

    # Filter retained clusters (size >= min_cluster_size)
    retained = {}
    for cid, info in all_clusters.items():
        if info['size'] >= min_cluster_size:
            # compute stability
            stability = sum(max(0, exit_l - info['birth']) for exit_l in info['exits'])
            retained[cid] = {'size': info['size'], 'stability': stability}

    # If no retained clusters, return empty
    if not retained:
        return {'clusters': [], 'selected_cluster_ids': []}

    # Sort retained clusters by decreasing stability, then cluster_id ascending
    sorted_retained = sorted(retained.keys(), key=lambda cid: (-retained[cid]['stability'], cid))

    # Selection: blocked set contains IDs that have a selected descendant
    selected = set()
    blocked = set()

    for cid in sorted_retained:
        if cid in blocked:
            continue
        selected.add(cid)
        # Block all ancestors (including through dropped clusters)
        anc = parent_map.get(cid)
        while anc is not None:
            blocked.add(anc)
            anc = parent_map.get(anc)

    # Sort selected IDs
    selected_ids = sorted(selected)

    # Build output clusters array (retained clusters, sorted by cluster_id for determinism)
    clusters_out = []
    for cid in sorted(retained.keys()):
        info = retained[cid]
        clusters_out.append({
            'cluster_id': cid,
            'size': info['size'],
            'stability': info['stability']
        })

    return {
        'clusters': clusters_out,
        'selected_cluster_ids': selected_ids
    }"
}
